UPDATE site_content
SET published_json = json_set(
  published_json,
  '$.home.heroDescription', 'Chalinze Steel Mills Ltd is developing a proposed integrated project at Vigwaza, Tanzania, founded on iron ore mining and preparation. Later ironmaking, steelmaking and billet production are planned stages, not operating facilities.',
  '$.home.introHeadline', 'From Tanzanian ore' || char(10) || 'to prepared feedstock.',
  '$.home.introPrimary', 'Chalinze Steel Mills Ltd is a Tanzanian registered company developing an integrated upstream operation that prepares run-of-mine iron ore into quality-controlled iron-bearing feedstock. Downstream ironmaking, steelmaking and billet production are planned stages of the wider project, not current operations.',
  '$.home.brandLabel', 'From Tanzanian minerals to iron-bearing materials'
)
WHERE content_key = 'site-config'
  AND json_extract(published_json, '$.home.introPrimary') = 'Chalinze Steel Mills Ltd is a Tanzanian registered company focused on developing an integrated iron ore mining, beneficiation and steel manufacturing operation, transforming run-of-mine iron ore into high-quality steel billets.';

