UPDATE site_content
SET published_json = json_set(
  published_json,
  '$.pages."/company".summary', 'Chalinze Steel Mills Ltd is developing the upstream foundation of a proposed integrated iron-and-steel project: mining, preparing and quality-controlling iron-bearing materials for later ironmaking and steel production.',
  '$.pages."/company".sections[0].body', 'Chalinze Steel Mills Ltd is a Tanzanian registered company developing an integrated iron-and-steel project. Its foundational upstream focus is iron ore mining, preparation and quality-controlled iron-bearing feedstock; downstream ironmaking and steelmaking are planned parts of the wider value chain, not current operations.'
)
WHERE content_key = 'site-config'
  AND json_extract(published_json, '$.pages."/company".summary') = 'Chalinze Steel Mills Ltd is a Tanzanian registered company focused on developing an integrated iron ore mining, beneficiation and steel manufacturing operation, transforming run-of-mine iron ore into high-quality steel billets.'
  AND json_extract(published_json, '$.pages."/company".sections[0].body') = 'Chalinze Steel Mills Ltd is a Tanzanian registered company focused on developing an integrated iron ore mining, beneficiation and steel manufacturing operation, transforming run-of-mine iron ore into high-quality steel billets.';

