  AND json_extract(draft_json, '$.pages."/company".sections[0].body') = 'Chalinze Steel Mills Ltd is a Tanzanian registered company focused on developing an integrated iron ore mining, beneficiation and steel manufacturing operation, transforming run-of-mine iron ore into high-quality steel billets.';

UPDATE site_content
SET published_json = json_set(
  published_json,
  '$.pages."/products".summary', 'Upstream iron-bearing feedstock is the project raw-material foundation. Planned downstream steel billets and examples such as rebar, wire rod and structural sections describe the integrated project potential, not products currently manufactured by Chalinze.',
  '$.pages."/products".sections', json('[
    {"title":"Upstream raw-material outputs","body":"Depending on ore characteristics and the selected route, upstream preparation may produce calibrated lump ore, beneficiated iron-ore concentrate, sinter feed or iron-ore pellets. The project feedstock specifications and route have not been confirmed.","tag":"Planned upstream output · specifications pending"},
    {"title":"Steel billets — integrated-project downstream","body":"Planning materials identify steel billets as a proposed downstream output after ironmaking, steelmaking and continuous casting. Two nominal cross-sections (130 × 130 mm and 150 × 150 mm) appear in project materials; final specifications and the approved capacity basis remain unresolved.","tag":"Planned downstream output · not in production"},
    {"title":"Primary downstream products — steel rolling","body":"At separate downstream facilities, billets may be rolled into reinforcement bars, structural steel sections, wire rods, round bars, and flat or square bars. These examples show potential industrial applications of the integrated project; they are not confirmed Chalinze products or facilities.","tag":"Illustrative downstream applications"},
    {"title":"Secondary downstream products — further processing","body":"Primary rolled products may be processed further into drawn wire, nails, binding wire, fencing, welded wire mesh and fasteners. These examples illustrate broader downstream value addition; they do not necessarily use billets directly and are not confirmed Chalinze manufacturing commitments.","tag":"Further processing · industry opportunity"}
  ]')
)
WHERE content_key = 'site-config'
  AND json_extract(published_json, '$.pages."/products".summary') = 'Steel billets are the principal planned product of the proposed integrated value chain. Two nominal cross-sections are listed; final specifications remain to be confirmed.'
  AND json_array_length(published_json, '$.pages."/products".sections') = 6
  AND json_extract(published_json, '$.pages."/products".sections[0].title') = '130 × 130 mm billet'
  AND json_extract(published_json, '$.pages."/products".sections[0].body') = 'A planned billet cross-section. Billet length, steel grade, chemistry, tolerances and mechanical properties remain to be confirmed.'
  AND json_extract(published_json, '$.pages."/products".sections[1].title') = '150 × 150 mm billet'
  AND json_extract(published_json, '$.pages."/products".sections[2].title') = 'Downstream uses'
  AND json_extract(published_json, '$.pages."/products".sections[3].title') = 'Technical data & availability'
  AND json_extract(published_json, '$.pages."/products".sections[4].title') = 'Quality You Can Trust'
  AND json_extract(published_json, '$.pages."/products".sections[5].title') = 'STEEL MAKING PROCESS'
  AND json_extract(published_json, '$.pages."/products".sections[5].body') = 'Explore the integrated steel manufacturing process, covering iron ore beneficiation, ironmaking, steelmaking and continuous casting to produce quality-assured steel billets. Steel billets are the primary finished products of Chalinze Steel Mills Ltd, manufactured for supply to downstream steel processors and manufacturers. Further conversion into reinforcement bars, structural steel and other finished steel products constitutes a separate downstream manufacturing activity.';

