UPDATE site_content
SET published_json = json_set(
  published_json,
  '$.eyebrow', 'Integrated iron & steel value chain · planned upstream development',
  '$.headline', 'FROM TANZANIAN IRON ORE TO METALLURGICAL-GRADE RAW MATERIALS',
  '$.introduction', 'Chalinze Steel Mills Ltd is developing an integrated upstream operation that prepares run-of-mine iron ore into quality-controlled iron-bearing materials for later ironmaking and steel production.',
  '$.valueStatement', 'The upstream operation is intended to establish reliable, consistent and quality-controlled iron-bearing feedstock. Downstream ironmaking, steelmaking and billet production describe the potential impact of this foundation and are not yet operating at Chalinze Steel Mills Ltd.',
  '$.stages', json('[
    {"id":"iron-ore-mining","title":"IRON ORE MINING","shortTitle":"Iron ore mining","status":"Planned upstream operation · mine and supply details to confirm","description":"Extraction of iron-bearing minerals through open-pit or underground mining, including drilling, blasting, excavation, loading and haulage of run-of-mine (ROM) ore. Mine ownership, permits, reserves, supply agreements and current extraction are not confirmed.","input":"Natural iron-ore deposits (resource and supply to confirm)","output":"Run-of-Mine (ROM) iron ore","machinery":"Drilling rigs, excavators, loaders and haul trucks are typical equipment; the mine fleet and mine plan are not confirmed.","operations":["Drilling","Blasting","Excavation","Loading","Haulage of ROM ore"],"technical":"No ore assay, resource estimate, reserve, mine permit, production rate or supply agreement has been supplied for publication.","hotspots":[{"label":"Mineral resource","detail":"Resource identification is part of the project concept. An approved geological resource statement and supporting assays have not been supplied."},{"label":"Material handling","detail":"Ore loading and haulage toward processing are conceptual material-flow steps, not verified installed equipment."}],"scene":"ore"},
    {"id":"crushing-screening","title":"CRUSHING & SCREENING","shortTitle":"Crushing & screening","status":"Planned process · design details pending","description":"Reduction of extracted ore into controlled particle sizes through primary, secondary and tertiary crushing, followed by screening and classification. The objective is a consistent, correctly sized feed for the selected processing route.","input":"Run-of-Mine (ROM) iron ore","output":"Crushed and screened iron ore of controlled particle size","machinery":"Jaw, gyratory and cone crushers with vibrating screens and classifiers; final equipment selection and duty are not confirmed.","operations":["Primary crushing","Secondary crushing","Tertiary crushing","Screening","Classification"],"technical":"No throughput, reduction ratio, particle-size target or equipment specification is asserted.","hotspots":[{"label":"Size reduction","detail":"Crushing stages illustrate progressive particle-size reduction; installed equipment and sizing strategy have not been confirmed."},{"label":"Screening & classification","detail":"Screening separates material by size. Cut sizes and screening efficiency depend on the approved process design."}],"scene":"beneficiation"},
    {"id":"beneficiation-concentration","title":"ORE BENEFICIATION & CONCENTRATION","shortTitle":"Beneficiation & concentration","status":"Planned process · route to confirm","description":"Physical processing may improve iron content and reduce unwanted gangue minerals and impurities through grinding, magnetic separation, gravity separation, flotation and other suitable technologies. The route depends on ore mineralogy.","input":"Crushed and screened iron ore","output":"Beneficiated iron ore concentrate","machinery":"SAG mills, ball mills and HPGR for grinding; magnetic and gravity separators and flotation cells for separation. Selection is not finalised.","operations":["Grinding and mineral liberation","Magnetic separation where applicable","Gravity separation where applicable","Flotation where applicable","Concentrate thickening"],"technical":"No iron grade, concentrate specification, recovery rate, process yield or water balance is asserted.","hotspots":[{"label":"Grinding & liberation","detail":"Grinding liberates iron-bearing minerals from gangue; mill selection and energy demand remain subject to design."},{"label":"Mineral separation","detail":"Separation illustrates the principle of upgrading iron-bearing material. No specific technology, recovery or concentrate grade is claimed."}],"scene":"beneficiation"},
    {"id":"dewatering-handling","title":"DEWATERING & MATERIAL HANDLING","shortTitle":"Dewatering & handling","status":"Planned process · design details pending","description":"Thickening, filtration, moisture control, stockpiling and blending can support consistent concentrate quality and prepare materials for subsequent processing. This stage stabilises concentrate before agglomeration or dispatch.","input":"Beneficiated iron ore concentrate (wet)","output":"Dewatered, moisture-controlled iron ore concentrate","machinery":"Thickeners, filter presses and vacuum filters, with conveyors, stackers, reclaimers and feeders; capacities are not confirmed.","operations":["Thickening","Filtration","Moisture control","Stockpiling","Blending"],"technical":"No moisture target, filtration rate, stockpile capacity or blending specification is supplied.","hotspots":[{"label":"Dewatering","detail":"Thickening and filtration reduce moisture for handling and further processing; equipment duty is not specified."},{"label":"Blending & stockpiling","detail":"Blending and stockpiling aim for consistent feed quality; no capacity or homogenisation result is claimed."}],"scene":"beneficiation"},
    {"id":"agglomeration-pelletizing","title":"AGGLOMERATION & PELLETIZING","shortTitle":"Agglomeration & pelletizing","status":"Route-dependent · technology to confirm","description":"Fine iron ore concentrates may be formed into pellets and indurated, or sintered where the selected ironmaking route requires it. Not every ore or route requires agglomeration; the need is established through process selection.","input":"Fine iron ore concentrate","output":"Iron ore pellets or sinter feed, where required","machinery":"Disc or drum pelletisers and induration furnaces, or sintering machines where required; final configuration is not selected.","operations":["Fine-concentrate preparation","Pelletising or sintering","Induration for pellets","Sizing and screening","Product handling"],"technical":"Whether agglomeration is required, and the choice between pellets and sinter, depend on mineralogical characterisation, metallurgical testing and selected ironmaking technology.","hotspots":[{"label":"Pelletising & induration","detail":"Pellets are formed from fine concentrate and hardened by induration; the circuit is conceptual and route-dependent."},{"label":"Sintering option","detail":"Sintering is an alternative agglomeration route where the ironmaking configuration requires sinter feed rather than pellets."}],"scene":"beneficiation"},
    {"id":"stockpiling-dispatch","title":"STOCKPILING, BLENDING & DISPATCH","shortTitle":"Stockpiling & dispatch","status":"Planned upstream output · dispatch framework to confirm","description":"Quality-controlled storage, blending, sampling and dispatch of prepared iron-bearing materials to downstream ironmaking facilities. This final upstream stage marks the boundary between feedstock preparation and downstream processing.","input":"Prepared iron-bearing materials: lump ore, concentrate, sinter feed or pellets","output":"Quality-controlled iron-bearing feedstock dispatched to downstream ironmaking","machinery":"Conveyors, stackers, reclaimers and feeders, with sampling systems, laboratories and analysers; capacities are representative only.","operations":["Quality-controlled storage","Blending","Sampling","Analysis","Product identification and traceability","Dispatch to downstream facilities"],"technical":"No stockpile capacity, sampling standard, product specification, logistics partner or delivery schedule has been verified.","hotspots":[{"label":"Sampling & quality control","detail":"Sampling and laboratory analysis support consistent feedstock quality; no standard or result is asserted."},{"label":"Dispatch boundary","detail":"Dispatch marks the upstream output boundary. Downstream ironmaking and steelmaking are not yet in operation at Chalinze."}],"scene":"inspection"}
  ]'),
  '$.quality', json('[
    {"stageId":"iron-ore-mining","title":"Incoming material","detail":"Assess raw-material identity, physical characteristics and chemical composition against project-approved criteria."},
    {"stageId":"crushing-screening","title":"Size control","detail":"Monitor particle-size distribution and screening efficiency. No numerical target is supplied."},
    {"stageId":"beneficiation-concentration","title":"Concentrate grade","detail":"Monitor iron content and reduction of gangue and impurities. No concentrate specification or recovery target is asserted."},
    {"stageId":"dewatering-handling","title":"Moisture & consistency","detail":"Control moisture and blending consistency so concentrate is stable for agglomeration or dispatch."},
    {"stageId":"agglomeration-pelletizing","title":"Agglomerate quality","detail":"Monitor pellet or sinter strength, sizing and consistency where agglomeration is part of the selected route."},
    {"stageId":"stockpiling-dispatch","title":"Dispatch & traceability","detail":"Sampling, product identification and traceability support quality-controlled dispatch of prepared feedstock."}
  ]'),
  '$.billet.description', 'Steel billets are a potential downstream output after ironmaking, steelmaking and continuous casting. They are semi-finished products for further processing, not upstream feedstock and not currently produced by Chalinze Steel Mills Ltd.',
  '$.approvalNote', 'This page describes the proposed upstream concept. Technical routes, equipment, product specifications, project status and imagery require approval against current company and engineering information before publication. Beneficiation and agglomeration are distinct and route-dependent: not every deposit requires the same processing stages, and not every ironmaking route requires pellets. Final configuration depends on mineralogical characterisation, metallurgical testing and technology selection.'
)
WHERE content_key = 'manufacturing'
  AND json_extract(published_json, '$.headline') = 'FROM TANZANIAN IRON ORE TO HIGH-QUALITY STEEL BILLETS'
  AND json_array_length(published_json, '$.stages') = 6
  AND json_extract(published_json, '$.stages[0].id') = 'rom-ore'
  AND json_extract(published_json, '$.stages[5].id') = 'inspection-dispatch';

